/**
 * ambient occlusion correction:
 * L = light value
 * N = number of non-occluded neighboors (0 to 2)
 * D = decay factor (= 2) [1 = full correction by avg, inf = no correction]
 * C = correction to add to L
 * -> C = round((3 - N) * L / (D * (N + 1)) + (3 - N))
 *
 * impl: L[16] -> L[8] (reduced precision) and get the correction C[16] on L[8]
 *
def cr(v, q):
	n = v >> 4
	a = v & 15
	# validity hint?: if n >= (4 << q) or a >= (4<<q):return 0xfff
	s = 3 - q
	d = 2
	n = min(round(4 * s * n / (d * (q + 1)) + s), (s * 16) - 1)
	a = min(round(4 * s * a / (d * (q + 1)) + s), (s * 16) - 1)
	return (n << 6) | a
 **/


